package app.veyra;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import app.veyra.data.CatalogBackend;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;
public final class EpisodeMonitor extends JobService {
 private static final int JOB=7302;private static volatile boolean checking;private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean stopped;private Future<?> task;private volatile int generation;
 static boolean active(){return checking;}
 private static List<String[]> entries(Context c){List<String[]> out=new ArrayList<>();for(String profile:ProfileStore.list(c).keySet())for(String key:FollowStore.list(ProfileStore.fixed(c,profile)).keySet())out.add(new String[]{profile,key});return out;}
 static void schedule(Context c){JobScheduler jobs=(JobScheduler)c.getSystemService(JOB_SCHEDULER_SERVICE);if(jobs==null)return;if(entries(c).isEmpty()){jobs.cancel(JOB);return;}if(jobs.getPendingJob(JOB)!=null)return;jobs.schedule(new JobInfo.Builder(JOB,new ComponentName(c,EpisodeMonitor.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(6*60*60*1000L,60*60*1000L).setPersisted(true).build());}
 static synchronized int check(Context c,BooleanSupplier stopped)throws Exception{if(!ConnectionState.online(c))throw new java.io.IOException("Connect to the Internet first");checking=true;int checked=0;List<String[]> entries=entries(c);int cursor=c.getSharedPreferences("episode-monitor",0).getInt("cursor",0);try{for(int n=0;n<Math.min(20,entries.size());n++){if(stopped.getAsBoolean()||Thread.currentThread().isInterrupted())break;String[] entry=entries.get((cursor+n)%entries.size());Context profile=ProfileStore.fixed(c,entry[0]);try{JSONObject record=FollowStore.list(profile).get(entry[1]);if(record==null)continue;JSONObject detail=CatalogBackend.get(c,record.getString("_provider")).detail(record.getString("id"),record.getString("audioType"),record.getString("_kind"));if(stopped.getAsBoolean()||Thread.currentThread().isInterrupted())break;int count=detail.getJSONArray("vod_collection").length();record.put("episodeCount",FollowStore.nextCount(record.getInt("episodeCount"),count)).put("lastChecked",System.currentTimeMillis());if(record.getInt("episodeCount")>record.getInt("notifiedCount")&&notify(c,entry[0],entry[1],record))record.put("notifiedCount",record.getInt("episodeCount"));if(PersonalStore.prefs(profile).contains(entry[1]))PersonalStore.prefs(profile).edit().putString(entry[1],record.toString()).apply();checked++;}catch(Exception|LinkageError ignored){/* Keep prior counts on partial catalog failures. */}}if(!entries.isEmpty())c.getSharedPreferences("episode-monitor",0).edit().putInt("cursor",(cursor+Math.min(20,entries.size()))%entries.size()).apply();return checked;}finally{checking=false;if(c.getApplicationContext() instanceof VeyraApplication)((VeyraApplication)c.getApplicationContext()).downloadFinished();}}
 private static boolean notify(Context c,String profile,String key,JSONObject record){if(!c.getSharedPreferences("settings",0).getBoolean("episodeNotices",true)||Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)return false;NotificationManager m=(NotificationManager)c.getSystemService(NOTIFICATION_SERVICE);if(m==null||!m.areNotificationsEnabled())return false;if(Build.VERSION.SDK_INT>=26)m.createNotificationChannel(new NotificationChannel("episodes","Followed series",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT>=26&&m.getNotificationChannel("episodes").getImportance()==NotificationManager.IMPORTANCE_NONE)return false;boolean privacy=c.getSharedPreferences("settings",0).getBoolean("privateEpisodeNotices",false);Intent open=new Intent(c,FollowOpenActivity.class).putExtra("profile",profile).putExtra("key",key);int id=(profile+key).hashCode()&0x7fffffff;PendingIntent intent=PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,"episodes"):new Notification.Builder(c);m.notify(id,b.setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle(privacy?"New episodes available":record.optString("vod_name")).setContentText(privacy?"Open Velixio to see followed-series updates":ProfileStore.list(c).get(profile)+" · "+(record.optInt("episodeCount")-record.optInt("notifiedCount"))+" additional episodes listed").setContentIntent(intent).setAutoCancel(true).build());return true;}
 public boolean onStartJob(JobParameters params){stopped=false;final int ticket=++generation;task=worker.submit(()->{try{check(this,()->stopped||ticket!=generation);}catch(Exception ignored){}if(!stopped&&ticket==generation)jobFinished(params,false);});return true;}
 public boolean onStopJob(JobParameters params){generation++;stopped=true;if(task!=null)task.cancel(true);return true;}
 public void onDestroy(){stopped=true;worker.shutdownNow();super.onDestroy();}
}
